import { Controller, Delete, Get, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '근태 담당자';
const USE_VALUES = ['사용', '미사용'];
const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 200;
// 가정: 차감 여부를 보내지 않으면 차감하지 않음(false)으로 등록한다.
const DEFAULT_DEDUCT_YN = false;

type Db = {
  execute(sql: string, params: Record<string, unknown>): Promise<number>;
};

function requiredMissing(): ApiError {
  return new ApiError(422, 'ATTENDANCE_ITEM_REQUIRED_MISSING', '필수 값이 누락되었거나 형식이 올바르지 않습니다.');
}

function nameOf(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '' || value.trim().length > 100) {
    throw requiredMissing();
  }
  return value.trim();
}

function useYnOf(value: unknown): string {
  if (typeof value !== 'string' || !USE_VALUES.includes(value)) {
    throw requiredMissing();
  }
  return value;
}

function deductYnOf(value: unknown): boolean {
  if (typeof value !== 'boolean') {
    throw new ApiError(400, 'VALIDATION_FAILED', '차감 여부는 true 또는 false여야 합니다.');
  }
  return value;
}

function idOf(value: string | undefined): string {
  if (value === undefined || !/^[0-9]+$/.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '근태항목 ID가 올바르지 않습니다.');
  }
  return value;
}

async function recordChange(db: Db, userId: string, targetId: unknown, changeType: string, content: string): Promise<void> {
  await db.execute(
    `INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at)
     VALUES (CAST(:userId AS bigint), 'attendance_item', CAST(:targetId AS bigint), :changeType, now(), :content, now(), now())`,
    { userId, targetId: String(targetId), changeType, content },
  );
}

@Controller('api/v1')
export class FnSfr01702Controller {
  @Get('/attendance-items')
  async listAttendanceItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const useYnRaw = query['useYn'];
    let useYn = '';
    if (useYnRaw !== undefined && useYnRaw !== null && useYnRaw !== '') {
      if (typeof useYnRaw !== 'string' || !USE_VALUES.includes(useYnRaw)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부가 올바르지 않습니다.');
      }
      useYn = useYnRaw;
    }
    const pageRaw = query['page'];
    const page = pageRaw === undefined || pageRaw === '' ? 0 : Number(pageRaw);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    const sizeRaw = query['size'];
    let size = sizeRaw === undefined || sizeRaw === '' ? DEFAULT_PAGE_SIZE : Number(sizeRaw);
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    if (size > MAX_PAGE_SIZE) {
      size = MAX_PAGE_SIZE;
    }
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT attendance_item_id AS "attendanceItemId", name AS "name", use_yn AS "useYn", deduct_yn AS "deductYn"
         FROM attendance_item
         WHERE (CAST(:useYn AS varchar) = '' OR use_yn = CAST(:useYn AS varchar))
         ORDER BY attendance_item_id
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { useYn, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM attendance_item
         WHERE (CAST(:useYn AS varchar) = '' OR use_yn = CAST(:useYn AS varchar))`,
        { useYn },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/attendance-items')
  @HttpCode(200)
  async createAttendanceItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const name = nameOf(data['name']);
    const useYn = useYnOf(data['useYn']);
    const deductYn = data['deductYn'] === undefined || data['deductYn'] === null
      ? DEFAULT_DEDUCT_YN
      : deductYnOf(data['deductYn']);
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT attendance_item_id FROM attendance_item WHERE name = :name',
        { name },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'ATTENDANCE_ITEM_DUPLICATED', '이미 같은 이름의 근태항목이 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO attendance_item (name, use_yn, deduct_yn, created_at, updated_at)
         VALUES (:name, :useYn, :deductYn, now(), now())
         RETURNING attendance_item_id AS "attendanceItemId"`,
        { name, useYn, deductYn },
      );
      const created = rows[0];
      await recordChange(
        db,
        user.id,
        created.attendanceItemId,
        '등록',
        `근태항목 등록: 이름=${name}, 사용 여부=${useYn}, 차감 여부=${deductYn}`,
      );
      return { attendanceItemId: created.attendanceItemId };
    });
  }

  @Patch('/attendance-items/:attendanceItemId')
  async updateAttendanceItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['attendanceItemId']);
    const data = checks.inputOf(req.body);
    const newName = data['name'] !== undefined ? nameOf(data['name']) : '';
    const newUseYn = data['useYn'] !== undefined ? useYnOf(data['useYn']) : '';
    const newDeduct = data['deductYn'] !== undefined ? String(deductYnOf(data['deductYn'])) : '';
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT attendance_item_id AS "attendanceItemId", name AS "name", use_yn AS "useYn", deduct_yn AS "deductYn"
         FROM attendance_item WHERE attendance_item_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_ITEM_NOT_FOUND', '근태항목을 찾을 수 없습니다.');
      }
      const before = found[0];
      if (newName !== '') {
        const dup = await db.query(
          `SELECT attendance_item_id FROM attendance_item
           WHERE name = :name AND attendance_item_id <> CAST(:id AS bigint)`,
          { name: newName, id },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'ATTENDANCE_ITEM_DUPLICATED', '이미 같은 이름의 근태항목이 있습니다.');
        }
      }
      await db.execute(
        `UPDATE attendance_item
         SET name = COALESCE(NULLIF(CAST(:name AS varchar), ''), name),
             use_yn = COALESCE(NULLIF(CAST(:useYn AS varchar), ''), use_yn),
             deduct_yn = COALESCE(CAST(NULLIF(CAST(:deductYn AS varchar), '') AS boolean), deduct_yn),
             updated_at = now()
         WHERE attendance_item_id = CAST(:id AS bigint)`,
        { name: newName, useYn: newUseYn, deductYn: newDeduct, id },
      );
      const afterName = newName === '' ? before.name : newName;
      const afterUseYn = newUseYn === '' ? before.useYn : newUseYn;
      const afterDeduct = newDeduct === '' ? before.deductYn : newDeduct === 'true';
      await recordChange(
        db,
        user.id,
        before.attendanceItemId,
        '수정',
        `근태항목 수정: 이름 ${before.name} → ${afterName}, 사용 여부 ${before.useYn} → ${afterUseYn}, 차감 여부 ${before.deductYn} → ${afterDeduct}`,
      );
      return { attendanceItemId: before.attendanceItemId };
    });
  }

  @Delete('/attendance-items/:attendanceItemId')
  async deleteAttendanceItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['attendanceItemId']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT attendance_item_id FROM attendance_item WHERE attendance_item_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_ITEM_NOT_FOUND', '근태항목을 찾을 수 없습니다.');
      }
      // TODO: 사용 이력 확인(ATTENDANCE_ITEM_IN_USE)은 근태 신청 테이블 정보가 없어 구현하지 못했다.
      await db.execute(
        'DELETE FROM attendance_item WHERE attendance_item_id = CAST(:id AS bigint)',
        { id },
      );
      return {};
    });
  }
}

