import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  Pager,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
const USE_OPTIONS: [string, string][] = [
  ['사용', '사용'],
  ['미사용', '미사용'],
];
const DEDUCT_OPTIONS: [string, string][] = [
  ['true', '차감'],
  ['false', '차감 안 함'],
];

type Mode =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row }
  | null;

export default function FnSfr01702Page({ role, notify }: PageProps) {
  const [useYnDraft, setUseYnDraft] = useState('');
  const [useYn, setUseYn] = useState('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const [name, setName] = useState('');
  const [formUseYn, setFormUseYn] = useState('사용');
  const [deduct, setDeduct] = useState('false');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-items', role, undefined, { useYn, page, size: SIZE }),
    [useYn, page, role],
  );

  function openCreate() {
    setName('');
    setFormUseYn('사용');
    setDeduct('false');
    setMode({ kind: 'create' });
  }

  function openEdit(row: Row) {
    setName(String(row.name ?? ''));
    setFormUseYn(String(row.useYn ?? '사용'));
    setDeduct(row.deductYn ? 'true' : 'false');
    setMode({ kind: 'edit', row });
  }

  function check() {
    if (name.trim() === '') {
      throw new Error('근태항목명을 입력해 주세요.');
    }
    if (formUseYn === '') {
      throw new Error('사용 여부를 선택해 주세요.');
    }
  }

  async function submitCreate() {
    check();
    await call('POST', '/attendance-items', role, {
      name: name.trim(),
      useYn: formUseYn,
      deductYn: deduct === 'true',
    });
    notify('근태항목을 등록했습니다.');
    setMode(null);
    reload();
  }

  async function submitEdit(row: Row) {
    check();
    await call('PATCH', `/attendance-items/${row.attendanceItemId}`, role, {
      name: name.trim(),
      useYn: formUseYn,
      deductYn: deduct === 'true',
    });
    notify('근태항목을 수정했습니다.');
    setMode(null);
    reload();
  }

  async function submitDelete(row: Row) {
    await call('DELETE', `/attendance-items/${row.attendanceItemId}`, role);
    notify('근태항목을 삭제했습니다.');
    setMode(null);
    reload();
  }

  const fields = (
    <>
      <Field label="근태항목명" required wide>
        <TextInput value={name} onChange={setName} />
      </Field>
      <Field label="사용 여부" required>
        <Select value={formUseYn} onChange={setFormUseYn} options={USE_OPTIONS} />
      </Field>
      <Field label="차감 여부">
        <Select value={deduct} onChange={setDeduct} options={DEDUCT_OPTIONS} placeholder="선택" />
      </Field>
    </>
  );

  return (
    <div>
      <h1>근태항목 관리</h1>
      <Filters
        onSearch={() => {
          setPage(0);
          setUseYn(useYnDraft);
        }}
        onReset={() => {
          setUseYnDraft('');
          setUseYn('');
          setPage(0);
        }}
      >
        <Field label="사용 여부">
          <Select value={useYnDraft} onChange={setUseYnDraft} options={USE_OPTIONS} placeholder="전체" />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={openCreate}>근태항목 등록</button>
      </Band>
      {error ? <p>{error}</p> : null}
      {loading && !data ? <p>불러오는 중입니다.</p> : null}
      <DataTable
        columns={[
          { key: 'name', label: '근태항목명' },
          { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r.useYn} /> },
          { key: 'deductYn', label: '차감 여부', render: (r) => (r.deductYn ? '차감' : '차감 안 함') },
          {
            key: 'actions',
            label: '처리',
            render: (r) => (
              <span>
                <button className="ghost" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
                <button className="ghost" onClick={(e) => { e.stopPropagation(); setMode({ kind: 'delete', row: r }); }}>삭제</button>
              </span>
            ),
          },
        ]}
        rows={data?.items ?? []}
        onRowClick={openEdit}
        empty="아직 등록한 근태항목이 없습니다. 근태항목 등록 버튼으로 추가해 주세요."
      />
      <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      {mode?.kind === 'create' ? (
        <Drawer title="근태항목 등록" onClose={() => setMode(null)}>
          <Form onSubmit={submitCreate} submit="등록">
            {fields}
          </Form>
        </Drawer>
      ) : null}
      {mode?.kind === 'edit' ? (
        <Drawer title="근태항목 수정" onClose={() => setMode(null)}>
          <Form onSubmit={() => submitEdit(mode.row)} submit="저장">
            {fields}
          </Form>
        </Drawer>
      ) : null}
      {mode?.kind === 'delete' ? (
        <Drawer title="근태항목 삭제" onClose={() => setMode(null)}>
          <Form
            onSubmit={() => submitDelete(mode.row)}
            submit="삭제"
            danger
            note={<p>삭제한 근태항목은 되돌릴 수 없습니다. 이미 사용한 항목은 삭제하지 말고 미사용으로 바꿔 주세요.</p>}
          >
            <p>{String(mode.row.name ?? '')} 항목을 삭제합니다.</p>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
